def minPath(grid, k):
    n = len(grid)

    # Find position of the smallest value (which is 1)
    start_i = start_j = 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_i, start_j = i, j
                break
        else:
            continue
        break

    res = [1]
    i, j = start_i, start_j
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for _ in range(k - 1):
        best_val = None
        best_pos = None
        for di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                v = grid[ni][nj]
                if best_val is None or v < best_val:
                    best_val = v
                    best_pos = (ni, nj)
        i, j = best_pos
        res.append(best_val)

    return res

